 19→function findDuplicateFileNames(files: File[]): string[] {
 20→  const seen = new Set<string>();
 21→  const duplicates = new Set<string>();
 22→  for (const file of files) {
 23→    if (seen.has(file.name)) {
 24→      duplicates.add(file.name);
 25→    }
 26→    seen.add(file.name);
 27→  }
 28→  return Array.from(duplicates);
 29→}
