 99→export async function runAgentLoop(
100→  message: string,
101→  agentSessionId: string | null,
102→  langfuseSessionId: string | null,
103→  conversationHistory: { role: string; content: string }[] | null,
104→  callbacks: AgentCallbacks,
105→  signal?: AbortSignal,
106→  userSessionId?: string,
107→  skills?: string[],
108→): Promise<void> {
109→  try {
110→    const response = await fetch('/api/chat', {
111→      method: 'POST',
112→      headers: {
113→        'Content-Type': 'application/json',
114→        ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
115→      },
116→      body: JSON.stringify({
117→        message,
118→        session_id: agentSessionId,
119→        langfuse_session_id: langfuseSessionId,
120→        conversation_history: conversationHistory ?? [],
121→        ...(skills?.length ? { skills } : {}),
122→      }),
123→      signal,
124→    });
125→
126→    if (!response.ok) {
127→      const errorText = await response.text();
128→      callbacks.onError(`Server error: ${errorText}`);
129→      return;
130→    }
131→
132→    await streamSSE(response, callbacks, signal);
133→  } catch (e: unknown) {
134→    if (signal?.aborted) return;
135→    const msg = e instanceof Error ? e.message : 'Connection failed';
136→    callbacks.onError(msg);
137→  }
138→}
