177→function handleSSEEvent(
178→  eventType: string,
179→  data: Record<string, unknown>,
180→  callbacks: AgentCallbacks,
181→) {
182→  switch (eventType) {
183→    case 'thinking':
184→    case 'answer':
185→      callbacks.onTextChunk(data.text as string);
186→      break;
187→    case 'thinking_done':
188→      callbacks.onThinkingDone();
189→      break;
190→    case 'tool_call':
191→      callbacks.onToolCall({
192→        toolCallId: (data.id as string) ?? '',
193→        toolName: (data.name as string) ?? undefined,
194→        sql: (data.sql as string) ?? '',
195→        command: (data.command as string) ?? undefined,
196→        toolInput: (data.input as Record<string, unknown>) ?? undefined,
197→        columns: [],
198→        rows: [],
199→        rowCount: 0,
200→      });
